package com.bank.loansimulation.application;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.bank.loansimulation.adapters.in.rest.SimulateLoanRequest;
import com.bank.loansimulation.adapters.in.rest.SimulateLoanResponse;
import com.bank.loansimulation.domain.error.BusinessError;
import com.bank.loansimulation.domain.port.SimulationRepository;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;

class SimulateLoanServiceTest {

    private static final String AMOUNT_MESSAGE = "El monto debe estar entre 1.000 y 50.000";
    private static final String TERM_MESSAGE = "El plazo debe estar entre 6 y 60 meses";

    record SavedCall(BigDecimal monto, Integer plazo, BigDecimal tasaAnual,
                     BigDecimal cuotaMensual, BigDecimal totalPagar, LocalDateTime fechaHora) {
    }

    static class FakeSimulationRepository implements SimulationRepository {
        final List<SavedCall> calls = new ArrayList<>();
        int nextNumber = 1;

        @Override
        public int save(BigDecimal monto, Integer plazo, BigDecimal tasaAnual, BigDecimal cuotaMensual,
                        BigDecimal totalPagar, LocalDateTime fechaHora) {
            calls.add(new SavedCall(monto, plazo, tasaAnual, cuotaMensual, totalPagar, fechaHora));
            return nextNumber++;
        }
    }

    private final FakeSimulationRepository repository = new FakeSimulationRepository();
    private final SimulateLoanService service = new SimulateLoanService(repository);

    private SimulateLoanResponse simulate(String monto, int plazo) {
        return service.execute(new SimulateLoanRequest(new BigDecimal(monto), plazo));
    }

    // ---------- RULE-001 ----------

    @Test
    void monto_below_minimum_is_rejected() {
        assertThatThrownBy(() -> simulate("500.00", 12))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    assertThat(((BusinessError) e).code()).isEqualTo("AMOUNT_OUT_OF_RANGE");
                    assertThat(e).hasMessage(AMOUNT_MESSAGE);
                });
    }

    @Test
    void monto_at_minimum_1000_is_valid() {
        SimulateLoanResponse response = simulate("1000.00", 12);
        assertThat(response).isNotNull();
    }

    @Test
    void monto_at_maximum_50000_is_valid() {
        SimulateLoanResponse response = simulate("50000.00", 12);
        assertThat(response).isNotNull();
    }

    // ---------- RULE-002 ----------

    @Test
    void plazo_above_maximum_is_rejected() {
        assertThatThrownBy(() -> simulate("10000.00", 72))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> {
                    assertThat(((BusinessError) e).code()).isEqualTo("TERM_OUT_OF_RANGE");
                    assertThat(e).hasMessage(TERM_MESSAGE);
                });
    }

    @Test
    void plazo_at_minimum_6_is_valid() {
        SimulateLoanResponse response = simulate("10000.00", 6);
        assertThat(response).isNotNull();
    }

    @Test
    void plazo_at_maximum_60_is_valid() {
        SimulateLoanResponse response = simulate("10000.00", 60);
        assertThat(response).isNotNull();
    }

    @Test
    void both_invalid_returns_only_the_amount_error() {
        assertThatThrownBy(() -> simulate("500.00", 72))
                .isInstanceOf(BusinessError.class)
                .satisfies(e -> assertThat(((BusinessError) e).code()).isEqualTo("AMOUNT_OUT_OF_RANGE"));
        assertThat(repository.calls).isEmpty();
    }

    // ---------- RULE-003 ----------

    @Test
    void plazo_12_has_rate_12_00() {
        assertThat(simulate("10000.00", 12).tasaAnual()).isEqualByComparingTo(new BigDecimal("12.00"));
    }

    @Test
    void plazo_13_has_rate_14_50() {
        assertThat(simulate("10000.00", 13).tasaAnual()).isEqualByComparingTo(new BigDecimal("14.50"));
    }

    @Test
    void plazo_24_has_rate_14_50() {
        assertThat(simulate("10000.00", 24).tasaAnual()).isEqualByComparingTo(new BigDecimal("14.50"));
    }

    @Test
    void plazo_36_has_rate_14_50() {
        assertThat(simulate("10000.00", 36).tasaAnual()).isEqualByComparingTo(new BigDecimal("14.50"));
    }

    @Test
    void plazo_37_has_rate_16_00() {
        assertThat(simulate("10000.00", 37).tasaAnual()).isEqualByComparingTo(new BigDecimal("16.00"));
