package com.bank.loansimulation.application;

import com.bank.loansimulation.adapters.in.rest.SimulateLoanRequest;
import com.bank.loansimulation.adapters.in.rest.SimulateLoanResponse;
import com.bank.loansimulation.domain.error.BusinessError;
import com.bank.loansimulation.domain.port.SimulationRepository;
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.time.LocalDateTime;

public class SimulateLoanService {

    private static final MathContext MC = new MathContext(40, RoundingMode.HALF_EVEN);
    private static final BigDecimal MIN_AMOUNT = new BigDecimal("1000.00");
    private static final BigDecimal MAX_AMOUNT = new BigDecimal("50000.00");
    private static final int MIN_TERM = 6;
    private static final int MAX_TERM = 60;

    private final SimulationRepository simulationRepository;

    public SimulateLoanService(SimulationRepository simulationRepository) {
        this.simulationRepository = simulationRepository;
    }

    public SimulateLoanResponse execute(SimulateLoanRequest request) {
        BigDecimal monto = request.monto();
        int plazo = request.plazo();

        // RULE-001
        if (monto.compareTo(MIN_AMOUNT) < 0 || monto.compareTo(MAX_AMOUNT) > 0) {
            throw new BusinessError("AMOUNT_OUT_OF_RANGE", null,
                    "El monto debe estar entre 1.000 y 50.000");
        }
        // RULE-002
        if (plazo < MIN_TERM || plazo > MAX_TERM) {
            throw new BusinessError("TERM_OUT_OF_RANGE", null,
                    "El plazo debe estar entre 6 y 60 meses");
        }

        // RULE-003
        BigDecimal tasaAnual;
        if (plazo <= 12) {
            tasaAnual = new BigDecimal("12.00");
        } else if (plazo <= 36) {
            tasaAnual = new BigDecimal("14.50");
        } else {
            tasaAnual = new BigDecimal("16.00");
        }

        // RULE-004
        BigDecimal i = tasaAnual
                .divide(BigDecimal.valueOf(100), MC)
                .divide(BigDecimal.valueOf(12), MC);
        BigDecimal growth = BigDecimal.ONE.add(i, MC).pow(plazo, MC);
        BigDecimal discount = BigDecimal.ONE.divide(growth, MC);
        BigDecimal denominator = BigDecimal.ONE.subtract(discount, MC);
        BigDecimal cuotaMensual = monto.multiply(i, MC)
                .divide(denominator, MC)
                .setScale(2, RoundingMode.HALF_UP);

        // RULE-005
        BigDecimal totalPagar = cuotaMensual
                .multiply(BigDecimal.valueOf(plazo))
                .setScale(2, RoundingMode.HALF_UP);

        // RULE-006
        int numeroCorrelativo = simulationRepository.save(
                monto, plazo, tasaAnual, cuotaMensual, totalPagar, LocalDateTime.now());

        return new SimulateLoanResponse(tasaAnual, cuotaMensual, totalPagar, numeroCorrelativo);
    }
}
